bool DesktopSessionAgent_Start_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::DesktopSessionAgent_Start_ResponseParams_Data* params =
      reinterpret_cast<
          internal::DesktopSessionAgent_Start_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for DesktopSessionAgent.0
  bool success = true;
  ::mojo::PendingAssociatedRemote<DesktopSessionControl> p_desktop_session_control{};
  DesktopSessionAgent_Start_ResponseParamsDataView input_data_view(params, message);
  
  if (success) {
    p_desktop_session_control =
        input_data_view.TakeDesktopSessionControl<decltype(p_desktop_session_control)>();
  }
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        DesktopSessionAgent::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_desktop_session_control));
  }
  return true;
}

void DesktopSessionAgent_Start_ProxyToResponder::Run(
    ::mojo::PendingAssociatedRemote<DesktopSessionControl> in_desktop_session_control) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply remoting::mojom::DesktopSessionAgent::Start", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("desktop_session_control"), in_desktop_session_control,
                        "<value of type ::mojo::PendingAssociatedRemote<DesktopSessionControl>>");
   });
#endif

  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);

  const size_t estimated_payload_size =
    0;
  mojo::Message message(
      std::to_underlying(messages::DesktopSessionAgent::kStart), kFlags, estimated_payload_size);
  mojo::internal::MessageFragment<
      ::remoting::mojom::internal::DesktopSessionAgent_Start_ResponseParams_Data> params(
          message);
  params.Allocate();

  
  mojo::internal::Serialize<::remoting::mojom::DesktopSessionControlAssociatedPtrInfoDataView>(
    in_desktop_session_control,
    &params->desktop_session_control,
    &params.message());

  
  MOJO_INTERNAL_CHECK_SERIALIZATION(
    mojo::internal::SendValidation::kDefault,
    !(!mojo::internal::IsHandleOrInterfaceValid(params->desktop_session_control)),
    mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_INTERFACE_ID,
    "invalid desktop_session_control in ");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(DesktopSessionAgent::Name_);
  message.set_method_name("Start");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

