// static
bool UnionTraits<::remoting::mojom::ReadChunkResult::DataView, ::remoting::mojom::ReadChunkResultPtr>::Read(
    ::remoting::mojom::ReadChunkResult::DataView input,
    ::remoting::mojom::ReadChunkResultPtr* output) {
  using UnionType = ::remoting::mojom::ReadChunkResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kData: {
      std::vector<uint8_t> result_data{};
      if (!input.ReadData(&result_data))
        return false;

      *output = UnionType::NewData(
          std::move(result_data));
      break;
    }
    case Tag::kError: {
      ::remoting::protocol::FileTransfer_Error result_error{};
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(
          std::move(result_error));
      break;
    }
    default:

      return false;
  }
  return true;
}

